     1→{% comment %}
     2→  Zip Code Checker — Theme App Extension Block
     3→  Add this block to any section in the Shopify Theme Editor.
     4→  The block automatically connects to your app — no manual configuration needed.
     5→{% endcomment %}
     6→
     7→{% if request.design_mode %}
     8→  {% comment %}
     9→    Theme Editor preview — render a static placeholder so no live API calls
    10→    are made during theme customization. The real widget loads on the storefront.
    11→  {% endcomment %}
    12→  <div style="
    13→    background:#ffffff;
    14→    border:1px solid #e1e3e5;
    15→    border-radius:8px;
    16→    padding:24px;
    17→    max-width:480px;
    18→    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    19→    box-sizing:border-box;
    20→    color:#202223;
    21→  ">
    22→    <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
    23→    <div style="display:flex;gap:8px;margin-bottom:12px;">
    24→      <input
    25→        type="text"
    26→        placeholder="Enter your zip code"
    27→        disabled
    28→        style="
    29→          flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
    30→          font-size:14px;background:#fafbfb;color:#202223;min-width:0;
    31→        "
    32→      >
    33→      <button
    34→        type="button"
    35→        disabled
    36→        style="
    37→          background:#008060;color:#fff;border:none;border-radius:8px;
    38→          padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
    39→          opacity:0.7;cursor:default;
    40→        "
    41→      >Check</button>
    42→    </div>
    43→    <div style="
    44→      background:#00806015;border-left:3px solid #008060;border-radius:8px;
    45→      padding:12px;font-size:14px;color:#008060;line-height:1.4;
    46→    ">
    47→      Great news! We deliver to your area.
    48→      <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
    49→    </div>
    50→    <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
    51→      Zip Code Checker — live widget loads on your storefront
    52→    </p>
    53→  </div>
    54→{% else %}
    55→
    56→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
    57→
    58→<div
    59→  id="zcc-widget-{{ block.id }}"
    60→  data-shop="{{ shop.permanent_domain }}"
    61→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
    62→  data-block="{{ block.id }}"
    63→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
    64→  {{ block.shopify_attributes }}
    65→></div>
    66→
    67→<script>
    68→(function () {
    69→  var ROOT_ID = "zcc-widget-{{ block.id }}";
    70→  var container = document.getElementById(ROOT_ID);
    71→  if (!container) return;
    72→
    73→  var SHOP = container.dataset.shop;
    74→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
    75→
    76→  // Try embedded config from metafield first (instant, no network needed)
    77→  var configStr = container.getAttribute("data-config");
    78→  if (configStr) {
    79→    try {
    80→      renderWidget(JSON.parse(configStr));
    81→      return;
    82→    } catch (e) {
    83→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
    84→    }
    85→  }
    86→
    87→  // Fallback: fetch config from API
    88→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    89→    .then(function (r) {
    90→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
    91→      return r.json();
    92→    })
    93→    .then(function (cfg) { renderWidget(cfg); })
    94→    .catch(function (err) {
    95→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
    96→      renderWidget({});
    97→    });
    98→
    99→  function renderWidget(cfg) {
   100→    // Merge with defaults
   101→    var D = {
   102→      position: "inline",
   103→      heading: "Check Delivery Availability",
   104→      placeholder: "Enter your zip code",
   105→      buttonText: "Check",
   106→      successMessage: "Great news! We deliver to your area.",
   107→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
   108→      notFoundMessage: "This zip code was not found in our system.",
   109→      primaryColor: "#008060",
   110→      successColor: "#008060",
   111→      errorColor: "#D72C0D",
   112→      backgroundColor: "#FFFFFF",
   113→      textColor: "#202223",
   114→      borderRadius: "8",
   115→      showEta: true,
   116→      showZone: false,
   117→      showWaitlistOnFailure: false,
   118→      showCod: true,
   119→      showReturnPolicy: true,
   120→      showCutoffTime: true,
   121→      showDeliveryDays: true,
   122→      customCss: "",
   123→    };
   124→    Object.keys(D).forEach(function (k) {
   125→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
   126→    });
   127→
   128→    var rad = cfg.borderRadius + "px";
   129→    var WID = "zcc-" + ROOT_ID;
   130→
   131→    if (cfg.position === "floating") {
   132→      renderFloating(cfg, WID, rad);
   133→    } else if (cfg.position === "popup") {
   134→      renderPopup(cfg, WID, rad);
   135→    } else {
   136→      renderInline(cfg, WID, rad);
   137→    }
   138→  }
   139→
   140→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
   141→  function injectCss(wid, cfg, rad) {
   142→    var css =
   143→      "#" + wid + "{" +
   144→        "background:" + cfg.backgroundColor + " !important;" +
   145→        "color:" + cfg.textColor + " !important;" +
   146→        "border-radius:" + rad + " !important;" +
   147→        "padding:24px !important;" +
   148→        "border:1px solid #e1e3e5 !important;" +
   149→        "max-width:480px;" +
   150→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
   151→        "box-sizing:border-box !important;" +
   152→      "}" +
   153→      "#" + wid + " *{box-sizing:border-box !important}" +
   154→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
   155→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
   156→      "#" + wid + " .zcc-input{" +
   157→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
   158→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
   159→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
   160→      "}" +
   161→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
   162→      "#" + wid + " .zcc-btn{" +
   163→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   164→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
   165→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
   166→      "}" +
   167→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
   168→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   169→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
   170→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
   171→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
   172→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
   173→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
   174→      "#" + wid + " .zcc-wl-input{" +
   175→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
   176→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
   177→      "}" +
   178→      "#" + wid + " .zcc-wl-btn{" +
   179→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
   180→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
   181→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
   182→      "}" +
   183→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   184→      "#" + wid + " .zcc-cutoff{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
   185→      "#" + wid + " .zcc-days{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
   186→      "#" + wid + " .zcc-cod{margin-top:4px !important;font-size:0.85em !important;font-weight:500 !important}" +
   187→      "#" + wid + " .zcc-cod--available{color:#008060 !important}" +
   188→      "#" + wid + " .zcc-cod--unavailable{color:#d72c0d !important}" +
   189→      "#" + wid + " .zcc-return-policy{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
   190→      (cfg.customCss || "");
   191→
   192→    var styleEl = document.createElement("style");
   193→    styleEl.textContent = css;
   194→    document.head.appendChild(styleEl);
   195→  }
   196→
   197→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
   198→  function buildWidgetInner(wid, cfg, btnLabel) {
   199→    return (
   200→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   201→      '<div class="zcc-row">' +
   202→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
   203→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   204→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   205→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
   206→      "</div>" +
   207→      '<div id="' + wid + '-res"></div>'
   208→    );
   209→  }
   210→
   211→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   212→    var inp = document.getElementById(wid + "-inp");
   213→    var btn = document.getElementById(wid + "-btn");
   214→    var res = document.getElementById(wid + "-res");
   215→    var btnLabel = cfg.buttonText;
   216→    if (!inp || !btn || !res) return;
   217→
   218→    function checkZip() {
   219→      var zip = inp.value.trim();
   220→      if (!zip) { inp.focus(); return; }
   221→
   222→      btn.disabled = true;
   223→      btn.textContent = "\u2026";
   224→      res.innerHTML = "";
   225→
   226→      fetch(
   227→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   228→          "&zip=" + encodeURIComponent(zip)
   229→      )
   230→        .then(function (r) { return r.json(); })
   231→        .then(function (data) {
   232→          btn.disabled = false;
   233→          btn.textContent = btnLabel;
   234→
   235→          if (data.allowed) {
   236→            var html = '<div class="zcc-result ok">' + esc(data.message);
   237→            if (cfg.showEta && data.eta) {
   238→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   239→            }
   240→            if (cfg.showZone && data.zone) {
   241→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   242→            }
   243→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   244→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   245→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   246→            }
   247→            if (cfg.showCutoffTime && data.cutoffTime) {
   248→              var parts = data.cutoffTime.split(':');
   249→              var hr = parseInt(parts[0], 10);
   250→              var min = parts[1] || '00';
   251→              var ampm = hr >= 12 ? 'PM' : 'AM';
   252→              var hr12 = hr % 12 || 12;
   253→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   254→            }
   255→            if (data.codAvailable === true) {
   256→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
   257→            } else if (data.codAvailable === false) {
   258→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
   259→            }
   260→            if (data.returnPolicy) {
   261→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
   262→            }
   263→            html += "</div>";
   264→            res.innerHTML = html;
   265→          } else {
   266→            var html = '<div class="zcc-result fail">' + esc(data.message);
   267→            if (cfg.showWaitlistOnFailure) {
   268→              html +=
   269→                '<div class="zcc-wl">' +
   270→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   271→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   272→                "</div>";
   273→            }
   274→            html += "</div>";
   275→            res.innerHTML = html;
   276→
   277→            if (cfg.showWaitlistOnFailure) {
   278→              var wBtn = document.getElementById(wid + "-wl-btn");
   279→              if (wBtn) {
   280→                wBtn.addEventListener("click", function () {
   281→                  var emailEl = document.getElementById(wid + "-wl-email");
   282→                  var email = emailEl ? emailEl.value.trim() : "";
   283→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   284→                  joinWaitlist(zip, email, wBtn);
   285→                });
   286→              }
   287→            }
   288→          }
   289→        })
   290→        .catch(function () {
   291→          btn.disabled = false;
   292→          btn.textContent = btnLabel;
   293→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   294→        });
   295→    }
   296→
   297→    btn.addEventListener("click", checkZip);
   298→    inp.addEventListener("keydown", function (e) {
   299→      if (e.key === "Enter") checkZip();
   300→    });
   301→  }
   302→
   303→  function joinWaitlist(zip, email, wBtn) {
   304→    wBtn.disabled = true;
   305→    wBtn.textContent = "Joining\u2026";
   306→
   307→    fetch(API_BASE + "/api/waitlist", {
   308→      method: "POST",
   309→      headers: { "Content-Type": "application/json" },
   310→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   311→    })
   312→      .then(function (r) { return r.json(); })
   313→      .then(function (data) {
   314→        var wlEl = wBtn.closest(".zcc-wl");
   315→        if (data.success) {
   316→          if (wlEl) wlEl.innerHTML =
   317→            '<p style="font-size:13px;margin:6px 0 0">' +
   318→            "\u2713 You\u2019ve been added to the waitlist!" +
   319→            "</p>";
   320→        } else {
   321→          wBtn.disabled = false;
   322→          wBtn.textContent = "Join Waitlist";
   323→        }
   324→      })
   325→      .catch(function () {
   326→        wBtn.disabled = false;
   327→        wBtn.textContent = "Join Waitlist";
   328→      });
   329→  }
   330→
   331→  // ── Inline position ─────────────────────────────────────────────────────────
   332→  function renderInline(cfg, WID, rad) {
   333→    injectCss(WID, cfg, rad);
   334→    container.id = WID;
   335→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
   336→    wireWidget(WID, cfg, API_BASE, SHOP);
   337→  }
   338→
   339→  // ── Floating position ────────────────────────────────────────────────────────
   340→  function renderFloating(cfg, WID, rad) {
   341→    // The original container becomes invisible (just an anchor)
   342→    container.style.display = "none";
   343→
   344→    injectCss(WID, cfg, rad);
   345→
   346→    // Additional styles for floating UI
   347→    var floatCss =
   348→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
   349→      "#" + WID + "-panel{" +
   350→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   351→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
   352→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
   353→      "}" +
   354→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
   355→      "#" + WID + "-panel .zcc-panel-header{" +
   356→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
   357→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
   358→      "}" +
   359→      "#" + WID + "-panel .zcc-panel-close{" +
   360→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
   361→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
   362→      "}" +
   363→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
   364→      "#" + WID + "-trigger{" +
   365→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   366→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
   367→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
   368→      "}" +
   369→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
   370→
   371→    var floatStyle = document.createElement("style");
   372→    floatStyle.textContent = floatCss;
   373→    document.head.appendChild(floatStyle);
   374→
   375→    // Build floating shell
   376→    var floatEl = document.createElement("div");
   377→    floatEl.id = WID + "-float";
   378→    floatEl.innerHTML =
   379→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
   380→        '<div class="zcc-panel-header">' +
   381→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
   382→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
   383→        '</div>' +
   384→        '<div id="' + WID + '">' +
   385→          buildWidgetInner(WID, cfg, cfg.buttonText) +
   386→        '</div>' +
   387→      '</div>' +
   388→      '<button id="' + WID + '-trigger" type="button">' +
   389→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
   390→        esc(cfg.buttonText || "Check Delivery") +
   391→      '</button>';
   392→
   393→    document.body.appendChild(floatEl);
   394→
   395→    // Wire toggle
   396→    var trigger = document.getElementById(WID + "-trigger");
   397→    var panel = document.getElementById(WID + "-panel");
   398→    var closeBtn = document.getElementById(WID + "-close");
   399→
   400→    if (trigger && panel) {
   401→      trigger.addEventListener("click", function () {
   402→        panel.classList.toggle("zcc-hidden");
   403→      });
   404→    }
   405→    if (closeBtn && panel) {
   406→      closeBtn.addEventListener("click", function () {
   407→        panel.classList.add("zcc-hidden");
   408→      });
   409→    }
   410→    // Close on outside click
   411→    document.addEventListener("click", function (e) {
   412→      if (!floatEl.contains(e.target)) {
   413→        if (panel) panel.classList.add("zcc-hidden");
   414→      }
   415→    });
   416→
   417→    wireWidget(WID, cfg, API_BASE, SHOP);
   418→  }
   419→
   420→  // ── Popup position ───────────────────────────────────────────────────────────
   421→  function renderPopup(cfg, WID, rad) {
   422→    injectCss(WID, cfg, rad);
   423→
   424→    var popupCss =
   425→      "#" + WID + "-overlay{" +
   426→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
   427→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
   428→      "}" +
   429→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
   430→      "#" + WID + "-modal{" +
   431→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   432→        "max-width:480px !important;width:100% !important;position:relative !important;" +
   433→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
   434→      "}" +
   435→      "#" + WID + "-modal .zcc-modal-close{" +
   436→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
   437→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
   438→      "}" +
   439→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
   440→      "#" + WID + "-popup-trigger{" +
   441→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   442→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
   443→        "cursor:pointer !important" +
   444→      "}" +
   445→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
